/// Currently only contains useful functions and some constants and typedefs
package floo_pkg;

  /// Currently Supported Routing Algorithms
  typedef enum logic[2:0] {
    /// `IdTable` routing uses a table of routing rules to determine to
    /// which output port a packet should be routed, based on the
    /// destination ID encoded in the header of the flit. Every router
    /// needs its own table, that is passed to `id_route_map_i`. The
    /// network interface only needs to convert the physical address to
    /// the destination ID, that is later used by the routers.
    IdTable,
    /// `SourceRouting` calculates the route to the destination in the
    /// source itself (i.e. the network interfaces). The route is encoded
    /// as a sequence of router ports that the packet should traverse. At
    /// every router hop, a port is popped from the route list. The routes
    /// need to be passed to the network interfaces `route_table_i`, which
    /// is a table of routes that can be indexed with the destination ID.
    /// This algorithm is mainly useful for smaller networks with fewer
    /// hops where the encoding size of the route does not become too large.
    SourceRouting,
    /// `XYRouting` is a simple routing algorithm that routes packets
    /// based on the XY coordinates of current and destination node. Every
    /// router needs to be aware of its own XY coordinates and forwards
    /// packets based on the difference of the coordinates. The network
    /// interface needs to convert the physical address to the destination
    ///  XY coordinates, which can be done with addressoffsets `XYAddrOffsetX`
    /// and `XYAddrOffsetY`, or by indexing the system address map `Sam`. This
    /// is controlled with the `UseIdTable` parameter.
    XYRouting,
    /// `YXRouting` is identical to `XYRouting` but resolves the Y dimension first,
    /// then the X dimension.
    YXRouting,
    /// `XYRoutingMirrored` is only meaningful for `floo_nw_router`: the
    /// narrow/wide-write request path uses `XYRouting`, while the
    /// narrow/wide-read response path uses `YXRouting`. Only legal when the
    /// wide channel is physically decoupled (`WideRwDecouple == Phys`).
    XYRoutingMirrored,
    /// `YXRoutingMirrored` is the mirror image of `XYRoutingMirrored`: the
    /// request path uses `YXRouting`, the response path uses `XYRouting`.
    YXRoutingMirrored
  } route_algo_e;

  /// True for any dimension-ordered routing algorithm (`XYRouting`,
  /// `YXRouting`, or one of the mirrored variants).
  function automatic bit is_dor_algo(route_algo_e algo);
    return algo == XYRouting || algo == YXRouting ||
           algo == XYRoutingMirrored || algo == YXRoutingMirrored;
  endfunction

  /// Concrete routing algorithm used by request-like paths for a possibly mirrored algorithm.
  function automatic route_algo_e route_algo_req(route_algo_e algo);
    unique case (algo)
      XYRoutingMirrored: return XYRouting;
      YXRoutingMirrored: return YXRouting;
      default:           return algo;
    endcase
  endfunction

  /// Concrete routing algorithm used by response-like paths for a possibly mirrored algorithm.
  function automatic route_algo_e route_algo_rsp(route_algo_e algo);
    unique case (algo)
      XYRoutingMirrored: return YXRouting;
      YXRoutingMirrored: return XYRouting;
      default:           return algo;
    endcase
  endfunction

